 title=re.sub('<[^>]+>', ' ', title)
 url=BASE+('/' if key=='index' else '/'+key+'.html'); esc=html.escape
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url,'publisher':{'@type':'Organization','name':'Merola Software & Services','url':BASE}}
 if key.startswith('guides/'):schema.update({'@type':'Article','headline':title,'dateModified':'2026-10-29','author':{'@type':'Organization','name':'Todoer team','url':BASE+'/about.html'}})
 head=f'<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Todoer</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#030712"><link rel="icon" href="/favicon.svg"><link rel="preconnect" href="https://fonts.bunny.net" crossorigin><link href="https://fonts.bunny.net/css?family=geist:400,500,600,700,800&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="/style.css"><script defer src="/site.js"></script>'
 for name,value in {'og:title':title+' · Todoer','og:description':desc,'og:url':url,'og:type':'article' if key.startswith('guides/') else 'website','og:site_name':'Todoer','og:locale':'en_US','og:image':BASE+'/assets/og.png','og:image:width':'1200','og:image:height':'630','og:image:type':'image/png','og:image:alt':'Todoer — Todos without the bullshit. Focused, open-source task management.'}.items():head+=f'<meta property="{name}" content="{esc(value)}">'
 for name,value in {'twitter:card':'summary_large_image','twitter:title':title,'twitter:description':desc,'twitter:image':BASE+'/assets/og.png','twitter:image:alt':'Todoer focused task management'}.items():head+=f'<meta name="{name}" content="{esc(value)}">'
 head+='<script type="application/ld+json">'+json.dumps(schema).replace('<','\\u003c')+'</script>'
 hero='' if key=='index' else f'<section class="wrap pagehero"><p class="eyebrow">TODOER / {key.split("/")[0].upper()}</p><h1>{pages[key][0]}</h1><p class="lead">{desc}</p></section>'
 out=f'<!doctype html><html lang="en"><head>{head}</head><body><a class="skip" href="#main">Skip to content</a><header class="wrap"><a class="brand" href="/"><img src="/favicon.svg" width="32" height="32" alt="">todoer<span>pro</span></a><nav aria-label="Main">{nav}</nav><a class="secondary" href="https://app.todoer.pro">Create your account ↗</a></header><main id="main" class="{"page-about" if key=="about" else ""}">{hero}{body}<section class="wrap closing"><p class="eyebrow">LESS FRICTION. MORE FOLLOW-THROUGH.</p><h2>Make room for your next good idea.</h2><a class="button" href="https://app.todoer.pro">Create your account ↗</a></section></main><footer class="wrap"><div class="brand">todoer<span>pro</span></div><p>A clearer head. A smaller next step.</p><nav aria-label="Footer">{nav}<a href="/agents.html">AI & agents</a><a href="/contact.html">Contact</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><a href="/cookies.html">Cookies</a><a href="/imprint.html">Legal notice</a></nav><p class="fine">© Merola Software & Services</p></footer></body></html>'
 p=W/(key+'.html');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(out)
